import sys, json, re

def unq(s):
    # s is a quoted po string "..."
    s = s.strip()
    assert s[0] == '"' and s[-1] == '"', s
    s = s[1:-1]
    out = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == '\\':
            n = s[i+1]
            out.append({'n':'\n','t':'\t','"':'"','\\':'\\'}.get(n, '\\'+n))
            i += 2
        else:
            out.append(c); i += 1
    return ''.join(out)

def q(s):
    return '"' + s.replace('\\','\\\\').replace('"','\\"').replace('\t','\\t').replace('\n','\\n') + '"'

def parse(path):
    text = open(path, encoding='utf-8').read()
    blocks = text.split('\n\n')
    entries = []
    for bi, b in enumerate(blocks):
        lines = b.split('\n')
        e = {'bi': bi, 'lines': lines, 'comments': [], 'ctxt': None, 'id': None, 'plural': None}
        cur = None
        fields = {}
        for ln in lines:
            if ln.startswith('#'):
                e['comments'].append(ln); continue
            m = re.match(r'^(msgctxt|msgid_plural|msgid|msgstr(?:\[\d+\])?) (".*")$', ln)
            if m:
                cur = m.group(1); fields[cur] = unq(m.group(2))
