        e['fields'] = fields
        entries.append(e)
    return text, blocks, entries

if __name__ == '__main__':
    cmd = sys.argv[1]; path = sys.argv[2]
    text, blocks, entries = parse(path)
    if cmd == 'dump':
        a, b = int(sys.argv[3]), int(sys.argv[4])
        real = [e for e in entries if e['id'] != '']
        for i, e in enumerate(real):
            if i < a or i >= b: continue
            cm = [c for c in e['comments'] if c.startswith('#.')]
            src = [c[3:] for c in e['comments'] if c.startswith('#:')]
            print(f"[{i}]" + (f" ctx={e['ctxt']!r}" if e['ctxt'] else '') + (' ' + ' '.join(cm) if cm else '') + (' @' + ','.join(s.split('/')[-1] for s in src) if src else ''))
            print('  ' + json.dumps(e['id'], ensure_ascii=False) + ((' | PL ' + json.dumps(e['plural'], ensure_ascii=False)) if e['plural'] else ''))
    elif cmd == 'count':
        print(len([e for e in entries if e['id'] != '']))
