import sys, re, runpy
sys.path.insert(0, '.')
from potool import parse, q
path = sys.argv[1]; kind = sys.argv[2]  # native|pages
batches = sys.argv[3:]
T = {}; R = {}
for b in batches:
    g = runpy.run_path(b)
    for k, v in g['T'].items():
        assert k not in T, f'dup {k} in {b}'
        T[k] = v
    R.update(g.get('R', {}))
text, blocks, entries = parse(path)
real = [e for e in entries if e['id'] != '']
ph_re = re.compile(r'%\d+%|%[-+ #0]*\d*(?:\.\d+)?(?:l|ll|z|h)?[sdgfuixc]|\{[^{}]*\}|<\d+/?>|</\d+>')
errs = []
for k, v in T.items():
    e = real[k]
    forms = v if isinstance(v, list) else [v]
    if kind == 'pages':
        forms = [f.replace("'", '’') for f in forms]
    lines = e['lines']
    # drop existing msgstr lines
    idx = next(i for i, l in enumerate(lines) if l.startswith('msgstr'))
    new = lines[:idx]
    if e['plural'] is not None:
        if len(forms) != 2: errs.append((k, 'plural forms')); continue
        for i, f in enumerate(forms): new.append(f'msgstr[{i}] {q(f)}')
    else:
        if len(forms) != 1: errs.append((k, 'forms')); continue
        new.append(f'msgstr {q(forms[0])}')
    # checks: newline counts, edge spaces, placeholders (native)
    src = e['id']
    for f in forms:
        if f.count('\n') != src.count('\n'): errs.append((k, 'newline count'))
        if (src[:1] == ' ') != (f[:1] == ' ') or (src[-1:] == ' ') != (f[-1:] == ' '): errs.append((k, 'edge space'))
        if kind == 'native':
            sp = sorted(re.findall(r'%\d+%', src + (e['plural'] or ''))) ; fp = sorted(re.findall(r'%\d+%', f))
            if sorted(set(sp)) != sorted(set(fp)): errs.append((k, f'boost ph {sp} {fp}'))
            sp2 = re.findall(r'%[sdgfu]', src); fp2 = re.findall(r'%[sdgfu]', f)
            if sp2 != fp2 and not (e['plural'] and len(fp2) <= len(sp2)): errs.append((k, f'printf ph {sp2} {fp2}'))
        if not f.strip(): errs.append((k, 'empty'))
    # comments
    if not any(l == '# AI Translated' for l in new):
        ins = 0
        while ins < len(new) and (new[ins] == '#' or new[ins].startswith('# ')): ins += 1
        add = ['# AI Translated']
        if k in R: add.append('# Needs human review: ' + R[k])
        new[ins:ins] = add
    blocks[e['bi']] = '\n'.join(new)
for x in errs: print('ERR', x)
open(path, 'w', encoding='utf-8').write('\n\n'.join(blocks))
print('applied', len(T), 'errors', len(errs))
EOF
